import itertools
from collections import Counter


def _route(data, minimum_duration, exact):
    required = data.get("required", [])
    bits = {name: 1 << i for i, name in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bits.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, 0)
    best = {start_state: data["start"]}
    queue = [(data["start"], *start_state)]
    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full
                and (not exact or used == data["coupons"])):
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < best.get(next_state, float("inf")):
                    best[next_state] = next_time
                    heapq.heappush(queue, (next_time, *next_state))
    return {"arrival": None}


def _route_solver(minimum_duration, exact):
    return lambda data: _route(data, minimum_duration, exact)


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        rank = (event.get("revision", 0), position)
        if event_id not in chosen or rank > chosen[event_id][0]:
            chosen[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    domains = []
    for name in names:
        blocked = set(data.get("blocked", {}).get(name, []))
        pin = data.get("pins", {}).get(name)
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked
                    and (pin is None or row["version"] == pin)]
        domains.append([-1] + versions)

    best_key = None
    best_assignment = None
    for values in itertools.product(*domains):
        assignment = dict(zip(names, values))
        if any(assignment.get(name, -1) < bounds[0]
               or assignment.get(name, -1) > bounds[1]
               for name, bounds in data.get("roots", {}).items()):
            continue

        installed = {name for name, version in assignment.items() if version != -1}
        closure = set()
        graph = {}
        pending = list(data.get("roots", {}))
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in closure:
                continue
            version = assignment.get(name, -1)
            if version == -1:
                valid = False
                break
            closure.add(name)
            row = next(row for row in packages[name] if row["version"] == version)
            active = [dep for dep in row.get("deps", [])
                      if not dep.get("feature") or dep["feature"] in features]
            graph[name] = []
            for dep in active:
                other = dep["name"]
                other_version = assignment.get(other, -1)
                if not dep["min"] <= other_version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(other)
                pending.append(other)
        if not valid or installed != closure:
            continue

        visiting, finished = set(), set()
        def cyclic(name):
            if name in visiting:
                return True
            if name in finished:
                return False
            visiting.add(name)
            if any(cyclic(other) for other in graph.get(name, [])):
                return True
            visiting.remove(name)
            finished.add(name)
            return False

        if any(cyclic(name) for name in graph):
            continue
        key = tuple(assignment[name] for name in names)
        if best_key is None or key < best_key:
            best_key = key
            best_assignment = assignment

    if best_assignment is None:
        return {"error": "unsatisfiable"}
    return {"versions": {name: version for name, version in best_assignment.items()
                          if version != -1}}


def _jobs(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for selected in itertools.combinations(jobs, data["k"]):
        ids = sorted(job["id"] for job in selected)
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in selected)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        intervals = sorted((job["start"], job["end"]) for job in selected)
        if any(intervals[i][0] < intervals[i - 1][1]
               for i in range(1, len(intervals))):
            continue
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value
                or (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


